pub(crate) fn grammar_emits_in(block: &Block, out: &mut Vec<Span>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Emit(_) => { out.push(stmt.span.clone()); },
            _ => { },
        }
        for inner in check_visit_stmt_blocks(&stmt.node) { grammar_emits_in(inner, out); }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn grammar_rule_emits(rule: &GrammarRule) -> bool {
    for alt in rule.alts.iter() {
        let action = match match alt.action.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let mut found: Vec<Span> = vec![];
        grammar_emits_in(&action, &mut found);
        if !found.is_empty() { return true; }
    }
    false
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn grammar_entry_emits(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, gram: &GrammarDef, entry: &str, rules: &collections::BTreeSet<String>) -> bool {
    let reached = grammar_reached_from(world, gram, entry, rules);
    for rule in gram.rules.iter() { if reached.contains(world.words.resolve(rule.name)) && grammar_rule_emits(rule) { return true; } }
    false
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) enum GrammarUndo {
    Absent,
    Undone(String),
    Passed(bool),
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn grammar_can_fail(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, pattern: &Pattern) -> bool {
    match pattern {
        Pattern::Repeat { rep, .. } => *rep != Repeat::Star && *rep != Repeat::Optional,
        Pattern::Cut => false,
        Pattern::Ref { name, args, .. } => {
            let name = *name;
            let called = world.words.resolve(name);
            !(called == "here" && args.is_empty() || called == "count" && args.len() == 1)
        },
        Pattern::Group(inner) => { let inner = nikaia_std::boxed::open(inner); grammar_can_fail(world, &inner.node) },
        Pattern::Bind { pat, .. } => { let pat = nikaia_std::boxed::open(pat); grammar_can_fail(world, &pat.node) },
        Pattern::Seq(parts) => parts.iter().any(|part| { grammar_can_fail(world, &part.node) }),
        Pattern::Choice(parts) => parts.iter().all(|part| { grammar_can_fail(world, &part.node) }),
        _ => true,
    }
}

